CREATE TABLE categories (id text PRIMARY KEY, parent_id text REFERENCES categories(id), name text NOT NULL, name_en text NOT NULL, slug text UNIQUE NOT NULL, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX categories_parent ON categories(parent_id);
CREATE TABLE products (id text PRIMARY KEY, category_id text NOT NULL REFERENCES categories(id), sku text UNIQUE NOT NULL, name text NOT NULL, name_en text NOT NULL, slug text UNIQUE NOT NULL, description text NOT NULL DEFAULT '', base_price_kip bigint NOT NULL CHECK(base_price_kip>=0), status text NOT NULL CHECK(status IN ('DRAFT','ACTIVE','ARCHIVED')), deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_category_status ON products(category_id,status) WHERE deleted_at IS NULL;
CREATE TABLE variants (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id), sku text UNIQUE NOT NULL, attributes jsonb NOT NULL DEFAULT '{}', price_override_kip bigint CHECK(price_override_kip>=0), stock_on_hand bigint NOT NULL DEFAULT 0 CHECK(stock_on_hand>=0), stock_reserved bigint NOT NULL DEFAULT 0 CHECK(stock_reserved>=0 AND stock_reserved<=stock_on_hand), position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX variants_product_position ON variants(product_id,position);
CREATE TABLE images (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id), url text NOT NULL, alt_text text NOT NULL DEFAULT '', position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX images_product ON images(product_id,position);
CREATE TABLE hero_slides (id text PRIMARY KEY, image_url text NOT NULL, alt_text text NOT NULL DEFAULT '', heading text NOT NULL DEFAULT '', subheading text NOT NULL DEFAULT '', cta_label text NOT NULL DEFAULT '', cta_href text NOT NULL DEFAULT '', position integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX hero_active ON hero_slides(active,position);
CREATE TABLE promo_banners (LIKE hero_slides INCLUDING ALL);
CREATE TABLE providers (id text PRIMARY KEY, name text NOT NULL, shipping_fee_kip bigint NOT NULL CHECK(shipping_fee_kip>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches (id text PRIMARY KEY, provider_id text NOT NULL REFERENCES providers(id), province text NOT NULL, city text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,province,city,name));
CREATE INDEX branches_provider ON branches(provider_id);
CREATE TABLE orders (bill_number text PRIMARY KEY, pickup_code text UNIQUE NOT NULL, recipient_phone text NOT NULL, recipient_name text NOT NULL, express_provider_id text NOT NULL REFERENCES providers(id), branch_id text NOT NULL REFERENCES branches(id), payment_type text NOT NULL CHECK(payment_type IN ('COD_PROVIDER','ONLINE')), payment_method text NOT NULL DEFAULT '', payment_status text NOT NULL CHECK(payment_status IN ('PENDING','PAID','REFUNDED')), order_status text NOT NULL CHECK(order_status IN ('PENDING_PAYMENT','CONFIRMED','DELIVERED','CANCELLED','EXPIRED')), subtotal_kip bigint NOT NULL CHECK(subtotal_kip>=0), shipping_fee_kip bigint NOT NULL CHECK(shipping_fee_kip>=0), total_kip bigint NOT NULL CHECK(total_kip>=0 AND total_kip::numeric=subtotal_kip::numeric+shipping_fee_kip::numeric), reservation_expires_at timestamptz, verified_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_phone ON orders(recipient_phone,created_at DESC);
CREATE INDEX orders_expiry ON orders(order_status,reservation_expires_at);
CREATE TABLE items (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(bill_number), product_variant_id text NOT NULL REFERENCES variants(id), product_name_snapshot text NOT NULL, unit_price_kip_snapshot bigint NOT NULL CHECK(unit_price_kip_snapshot>=0), quantity bigint NOT NULL CHECK(quantity BETWEEN 1 AND 99), line_total_kip bigint NOT NULL CHECK(line_total_kip>=0 AND line_total_kip::numeric=unit_price_kip_snapshot::numeric*quantity), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX items_order ON items(order_id);
CREATE INDEX items_variant ON items(product_variant_id);
CREATE TABLE order_events (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(bill_number), action text NOT NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_order ON order_events(order_id,created_at);
CREATE TABLE attempts (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(bill_number), provider text NOT NULL, bank text NOT NULL, provider_transaction_id text, amount_kip bigint NOT NULL CHECK(amount_kip>=0), status text NOT NULL CHECK(status IN ('PENDING','CREATED','PAID','FAILED','EXPIRED')), qr_code text NOT NULL DEFAULT '', deeplink text NOT NULL DEFAULT '', expires_at timestamptz NOT NULL, last_error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_transaction_id));
CREATE INDEX attempts_order ON attempts(order_id,created_at DESC);
CREATE UNIQUE INDEX attempts_one_open ON attempts(order_id) WHERE status IN ('PENDING','CREATED');
CREATE TABLE payment_events (id text PRIMARY KEY, provider text NOT NULL, provider_transaction_id text NOT NULL, dedupe_key text UNIQUE NOT NULL, bill_number text NOT NULL DEFAULT '', normalized_status text NOT NULL CHECK(normalized_status IN ('COMPLETED','REJECTED','UNKNOWN')), amount_kip bigint, raw_body text NOT NULL, outcome text NOT NULL DEFAULT 'PENDING', processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX payment_events_transaction ON payment_events(provider,provider_transaction_id);
CREATE TABLE refunds (id text PRIMARY KEY, payment_attempt_id text NOT NULL REFERENCES attempts(id), order_id text NOT NULL REFERENCES orders(bill_number), amount_kip bigint NOT NULL CHECK(amount_kip>=0), reason text NOT NULL, status text NOT NULL CHECK(status IN ('REQUESTED','APPROVED','SUBMITTED','PROCESSING','SUCCEEDED','REJECTED','FAILED','UNKNOWN','MANUAL_REVIEW')), provider_refund_bill_id text UNIQUE, provider_status text NOT NULL DEFAULT '', requested_by text NOT NULL, approved_by text NOT NULL DEFAULT '', last_error text NOT NULL DEFAULT '', submitted_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX refunds_one_active ON refunds(order_id) WHERE status IN ('REQUESTED','APPROVED','SUBMITTED','PROCESSING','UNKNOWN','MANUAL_REVIEW');
CREATE INDEX refunds_status ON refunds(status,updated_at);
CREATE TABLE otp_codes (id text PRIMARY KEY, phone text NOT NULL, code_hash text NOT NULL, expires_at timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX otp_phone ON otp_codes(phone,created_at DESC);
CREATE TABLE phone_tokens (id text PRIMARY KEY, phone text NOT NULL, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE staff_users (id text PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, role text NOT NULL CHECK(role IN ('OWNER','CATALOG','FULFILMENT','FINANCE','SUPPORT','AUDITOR')), password_hash text NOT NULL, disabled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE staff_sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES staff_users(id), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON staff_sessions(user_id);
CREATE TABLE audit_logs (id text PRIMARY KEY, actor_email text NOT NULL, actor_role text NOT NULL, actor_legacy boolean NOT NULL, action text NOT NULL, target_type text NOT NULL, target_id text NOT NULL DEFAULT '', summary text NOT NULL DEFAULT '', ip text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_created ON audit_logs(created_at DESC);
