CREATE TABLE outbox_events (id text PRIMARY KEY, phone text NOT NULL, message text NOT NULL, dedupe_key text UNIQUE NOT NULL, status text NOT NULL CHECK(status IN ('PENDING','SENDING','SENT','FAILED','DEAD')), attempts integer NOT NULL DEFAULT 0, last_error text NOT NULL DEFAULT '', available_at timestamptz NOT NULL, lease_until timestamptz, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_due ON outbox_events(status,available_at);
CREATE TABLE sms_logs (id text PRIMARY KEY, phone text NOT NULL, message text NOT NULL, accepted boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sms_phone ON sms_logs(phone,created_at DESC);
CREATE TABLE idempotency_keys (id text PRIMARY KEY, scope text NOT NULL, key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope,key));
CREATE INDEX idempotency_expiry ON idempotency_keys(expires_at);

